rules.logic:
if (element._widgetsMoved) return;
element._widgetsMoved = true;
var searchList = element.querySelector('#search-result');
if (!searchList) return;

var imagesItem = document.querySelector('li[data-fast-name="images"]');
var videoItem = document.querySelector('li[data-fast-name="video-unisearch"]');

if (imagesItem && imagesItem.parentElement) {
    var clonedImages = imagesItem.cloneNode(true);
    searchList.insertBefore(clonedImages, searchList.firstChild);
}

if (videoItem && videoItem.parentElement) {
    var clonedVideo = videoItem.cloneNode(true);
    if (searchList.firstChild) {
        searchList.insertBefore(clonedVideo, searchList.firstChild.nextSibling);
    } else {
        searchList.insertBefore(clonedVideo, searchList.firstChild);
    }
}
